// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract with a dummy address (non-zero) for lrtConfig
        address dummyLrtConfig = address(0xdead);
        c.initialize(dummyLrtConfig);

        // Set up a random address to call addNodeDelegatorContractToQueue
        address caller = address(0xbeef);
        address[] memory nodeDelegators = new address[](1);
        nodeDelegators[0] = address(0x1234);

        // In the reference contract (paused=false), the call should succeed
        // In the mutant (paused always true), the call should revert due to whenNotPaused
        bool ok;
        try c.addNodeDelegatorContractToQueue(nodeDelegators) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: succeeds (ok == true), Mutant: reverts (ok == false)
        assertTrue(ok);
    }
}

