pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        c.initialize(address(this));

        // Pause the contract
        // In the correct contract, pause() sets _paused to true;
        // in the buggy version, pause() always returns true regardless of state, so we call pause() to set the state consistently
        c.pause();

        // Now call addNodeDelegatorContractToQueue
        address[] memory ndcs = new address[](1);
        ndcs[0] = address(0xdead);

        // The correct contract: addNodeDelegatorContractToQueue reverts because contract is paused (whenNotPaused modifier)
        // The buggy contract: addNodeDelegatorContractToQueue reverts because paused() always returns true, but the modifier is whenNotPaused, so it also reverts
        // But the difference specified is about the return value of paused() itself, not about revert behavior.
        // The difference: paused() returns a different value. So we can check the return value of paused() directly.
        // In both contracts, after pause() is called, paused() should return true. But in the buggy version, paused() always returns true regardless.
        // So the assertion should be that paused() returns true in both. That doesn't diverge.
        // We need a scenario where paused() returns false in the correct contract but true in the buggy one.
        // That is: before any pause/unpause, the correct contract returns false, the buggy one returns true.
        // So we don't call pause(). Just deploy and check.
        bool p = c.paused();
        assertTrue(p, "paused() should return true in buggy version, but in reference it returns false");
    }
}

