import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        c.initialize(address(0xdead));

        // Add a node delegator (this should succeed in both versions)
        address[] memory nd = new address[](1);
        nd[0] = address(0xbeef);
        c.addNodeDelegatorContractToQueue(nd);

        // The paused() function should return false in the correct version and true in the buggy version
        bool isPaused = c.paused();
        // In the correct version, paused() returns false; in the buggy version, it returns true.
        // So we assert that it is NOT true (i.e., it's false) to make the reference pass.
        assertTrue(!isPaused, "paused() should be false in reference");
    }
}

