        nds[0] = address(nd);
        c.addNodeDelegatorContractToQueue(nds);

        // Now getTotalAssetDeposits for asset should be 1e18
        // Reference: 0 + 1e18 + 0 = 1e18
        // Bug: 0 - 1e18 + 0 = underflows to uint256 max
        uint256 depositLimit = config.depositLimitByAsset(address(asset));
        uint256 currentLimit = c.getAssetCurrentLimit(address(asset));
        // depositLimit - 1e18 should be the reference limit
        // Bug limit = depositLimit - type(uint256).max = underflow
        assertTrue(currentLimit <= depositLimit);
    }
}

